const raw = $input.first().json;
const data = raw.body;

console.log('📬 Received:', JSON.stringify(data, null, 2));

// Quelle prüfen
if (!data.source || data.source !== 'webhook') {
  console.log('⏭️ Skipping - wrong source');
  return [];
}

// Email prüfen
if (!data.creatorEmail) {
  console.log('⚠️ No email');
  return [];
}

// Statusänderung prüfen
const isStatusChange = !!(data.oldStatus && data.newStatus);
console.log('🔍 Status change:', isStatusChange);

if (!isStatusChange) {
  return [];
}

// Board-Status-Namen
const statusNames = {
  'boardTriage': 'Triage',
  'boardToDo': 'To Do',
  'boardProgress': 'In Bearbeitung',
  'boardFeedback': 'Feedback',
  'boardDone': 'Erledigt'
};

const statusEmojis = {
  'boardTriage': '🔍',
  'boardToDo': '📋',
  'boardProgress': '⚙️',
  'boardFeedback': '⏳',
  'boardDone': '✅'
};

return {
  json: {
    taskId: data.taskId,
    taskTitle: data.taskTitle || 'Aufgabe',
    oldStatus: statusNames[data.oldStatus] || data.oldStatus,
    newStatus: statusNames[data.newStatus] || data.newStatus,
    statusEmoji: statusEmojis[data.newStatus] || '🔔',
    creatorEmail: data.creatorEmail,
    creatorName: data.creatorName || 'User',
    updatedBy: data.updatedBy || 'Team',
    formattedDate: new Date().toLocaleString('de-DE')
  }
};
